package com.example.rokidkeyboardbridge;
import android.content.*;import android.widget.*;import android.text.*;import android.text.style.*;import android.graphics.*;import org.json.*;import java.time.*;import java.io.*;
public final class HealthMetricsLineDeviceChecks {
 static int n;static void ok(boolean b){if(!b)throw new AssertionError("health HUD "+n);n++;}
 public static int run(Context c)throws Exception{n=0;long now=System.currentTimeMillis();ZoneId z=ZoneId.systemDefault();String day=Instant.ofEpochMilli(now).atZone(z).toLocalDate().toString();StepsExerciseAdvice.Sample steps=new StepsExerciseAdvice.Sample("歩数 1234",now,"Health Connect");JSONObject energy=new JSONObject().put("balanceKcal",550).put("observedAt",now).put("source","HEALBE_SCREEN").put("date",day);
  String fresh=HealthMetricsLine.format(steps,energy,now,z);ok(fresh.contains("歩数 1234")&&fresh.contains("収支+550kcal※"));ok(HealthMetricsLine.format(steps,new JSONObject(energy.toString()).put("balanceKcal",-550),now,z).contains("収支-550kcal※"));ok(HealthMetricsLine.format(steps,new JSONObject(energy.toString()).put("balanceKcal",0),now,z).contains("収支0kcal※"));
  ok(HealthMetricsLine.format(steps,null,now,z).contains("収支 --"));ok(HealthMetricsLine.format(steps,new JSONObject(energy.toString()).put("source","unknown"),now,z).contains("収支 --"));ok(HealthMetricsLine.format(steps,new JSONObject(energy.toString()).put("observedAt",now-900001),now,z).contains("kcal(15分前)"));ok(HealthMetricsLine.format(steps,new JSONObject(energy.toString()).put("date","2000-01-01"),now,z).contains("収支 --(日付確認)"));
  JSONObject sdk=new JSONObject(energy.toString()).put("source","HEALBE_SDK").put("measuredAt",now-1000);ok(HealthMetricsLine.format(steps,sdk,now,z).contains("+550kcal※"));ok(HealthMetricsLine.format(steps,new JSONObject(sdk.toString()).put("measuredAt",now-900001),now,z).contains("kcal※(同期0分前)"));ok(HealthMetricsLine.format(steps,new JSONObject(sdk.toString()).put("measuredAt",now-3180000).put("observedAt",now-360000),now,z).contains("同期6分前"));ok(HealthMetricsLine.format(steps,new JSONObject(sdk.toString()).put("measuredAt",now-3600000).put("observedAt",now-1200000),now,z).contains("kcal(同期20分前)"));JSONObject unknownTime=new JSONObject(sdk.toString());unknownTime.remove("measuredAt");ok(HealthMetricsLine.format(steps,unknownTime,now,z).contains("収支 --"));
  float density=c.getResources().getDisplayMetrics().density;int width=Math.round(216*density),height=Math.round(72*density);Bitmap image=Bitmap.createBitmap(width,height*2,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);canvas.drawColor(Color.BLACK);
  for(int i=0;i<2;i++){
   TextView view=new TextView(c);view.setTextColor(Color.WHITE);view.setTextSize(10.5f);view.setLineSpacing(0,.8f);view.setPadding(2,0,2,0);
   String header="10/29(木) 13:30",line=i==0?fresh:HealthMetricsLine.format(new StepsExerciseAdvice.Sample("歩数 200000",now,"Health Connect"),new JSONObject(sdk.toString()).put("balanceKcal",15000),now,z);
   SpannableString text=new SpannableString(header+"\nB100% Wi-Fi/NET OK\n"+line+"\n天気 曇り 35.0℃\n現在地 東京都立川市"+(i==1?"\n保留通知 2件":""));text.setSpan(new RelativeSizeSpan(1.7f),0,header.length(),Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);view.setText(text);view.measure(android.view.View.MeasureSpec.makeMeasureSpec(width,1073741824),android.view.View.MeasureSpec.makeMeasureSpec(height,1073741824));view.layout(0,0,width,height);Layout layout=view.getLayout();ok(layout!=null);ok(layout.getLineBottom(layout.getLineCount()-1)<=height-view.getPaddingBottom());
   canvas.save();canvas.translate(0,i*height);view.draw(canvas);canvas.restore();
  }
  try(FileOutputStream out=new FileOutputStream(new File(c.getFilesDir(),"energy-hud-native.png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();return n;
 }
}
